// calculateDepth AST 깊이 계산
func calculateDepth(node *Node) int {
	if node == nil {
		return 0
	}
	maxChildDepth := 0
	for _, child := range node.Children {
		childDepth := calculateDepth(child)
		if childDepth > maxChildDepth {
			maxChildDepth = childDepth
		}
	}
	return 1 + maxChildDepth
}

